--
-- Table structure for table `bank_savings_accounts`
--

DROP TABLE IF EXISTS `bank_savings_accounts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bank_savings_accounts` (
  `sm_id` varchar(10) NOT NULL,
  `user_id` varchar(50) NOT NULL,
  `cif_id` varchar(50) NOT NULL,
  `ifsc_code` varchar(50) NOT NULL,
  `account_no` varchar(20) NOT NULL,
  `pan_id` varchar(20) NOT NULL,
  `email` varchar(60) NOT NULL,
  `account_name` varchar(100) NOT NULL,
  `guardian_name` varchar(100) DEFAULT NULL,
  `phone_no` varchar(20) NOT NULL,
  `address` varchar(500) NOT NULL,
  `district` varchar(50) DEFAULT NULL,
  `state` varchar(50) DEFAULT NULL,
  `pin_code` varchar(30) DEFAULT NULL,
  `date_of_issue` varchar(50) DEFAULT NULL,
  `is_joint` varchar(1) NOT NULL,
  `joint_id` varchar(20) DEFAULT NULL,
  `is_nominee` varchar(50) DEFAULT NULL,
  `nominee_id` varchar(10) DEFAULT NULL,
  `nominee_name` varchar(50) DEFAULT NULL,
  `nominee_phone` varchar(15) DEFAULT NULL,
  `nominee_address` varchar(200) DEFAULT NULL,
  `current_balance` decimal(10,2) DEFAULT NULL,
  `interest_rate` decimal(3,2) DEFAULT NULL,
  `if_freeze` varchar(1) DEFAULT NULL,
  `freeze_reason` varchar(20) DEFAULT NULL,
  `last_transaction_date` datetime DEFAULT NULL,
  `last_update_on` datetime DEFAULT NULL,
  `currency` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`sm_id`),
  UNIQUE KEY `sm_id` (`sm_id`),
  UNIQUE KEY `user_id` (`user_id`),
  UNIQUE KEY `cif_id` (`cif_id`),
  UNIQUE KEY `pan_id` (`pan_id`),
  KEY `ifsc_code` (`ifsc_code`),
  CONSTRAINT `bank_savings_accounts_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `bank_authentication` (`user_id`),
  CONSTRAINT `bank_savings_accounts_ibfk_2` FOREIGN KEY (`ifsc_code`) REFERENCES `branch_details` (`ifsc_code`),
  CONSTRAINT `bank_savings_accounts_ibfk_3` FOREIGN KEY (`cif_id`) REFERENCES `crmuser_accounts` (`cif_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

