--
-- Table structure for table `crmuser_employees`
--

DROP TABLE IF EXISTS `crmuser_employees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `crmuser_employees` (
  `user_id` varchar(15) NOT NULL,
  `ifsc_code` varchar(12) NOT NULL,
  `emp_id` varchar(30) NOT NULL,
  `user_name` varchar(100) NOT NULL,
  `email` varchar(60) NOT NULL,
  `ph_no` varchar(20) NOT NULL,
  `is_admin` varchar(3) NOT NULL,
  `manager_name` varchar(100) NOT NULL,
  `job_role` varchar(50) NOT NULL,
  `is_retired` varchar(3) NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `last_updated_on` datetime DEFAULT NULL,
  PRIMARY KEY (`emp_id`),
  UNIQUE KEY `user_id` (`user_id`),
  UNIQUE KEY `emp_id` (`emp_id`),
  KEY `ifsc_code` (`ifsc_code`),
  CONSTRAINT `crmuser_employees_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `bank_authentication` (`user_id`),
  CONSTRAINT `crmuser_employees_ibfk_2` FOREIGN KEY (`ifsc_code`) REFERENCES `branch_details` (`ifsc_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

